<?php
require_once '../../config/config.php';
require_once '../../config/database.php';
require_once '../../includes/access.php';
if (session_status() === PHP_SESSION_NONE) { session_start(); }
if (!isset($_SESSION['user_id'])) { header('Location: ../../login.php'); exit; }
access_require_roles(array('Admin'));
$conn->set_charset('utf8mb4');
function fee_e($v) { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
$message=''; $error='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (access_is_student()) { http_response_code(403); exit('Students have view-only fee access.'); }
    $action=(string)($_POST['action']??'');
    if ($action==='type') {
        $name=trim((string)($_POST['fee_name']??'')); $desc=trim((string)($_POST['description']??''));
        $stmt=$conn->prepare('INSERT INTO fee_types (fee_name,description) VALUES (?,?)'); $stmt->bind_param('ss',$name,$desc);
        if ($name==='' || !$stmt->execute()) $error=$stmt->errno===1062?'Fee type already exists.':($stmt->error?:'Enter a fee name.'); else $message='Fee type added.'; $stmt->close();
    } elseif ($action==='structure') {
        $class=(int)$_POST['class_id'];$type=(int)$_POST['fee_type_id'];$amount=(float)$_POST['amount'];$frequency=(string)$_POST['frequency'];
        $stmt=$conn->prepare('INSERT INTO fee_structures (class_id,fee_type_id,amount,frequency) VALUES (?,?,?,?) ON DUPLICATE KEY UPDATE amount=VALUES(amount), status=1');$stmt->bind_param('iids',$class,$type,$amount,$frequency);
        if ($class<=0||$type<=0||$amount<0||!in_array($frequency,array('Monthly','Quarterly','Annual','One Time'),true)||!$stmt->execute())$error=$stmt->error?:'Enter valid fee structure details.';else$message='Fee structure saved.';$stmt->close();
    } elseif ($action==='schedule') {
        $structure=(int)$_POST['fee_structure_id'];$date=(string)$_POST['due_date'];$amount=(float)$_POST['schedule_amount'];
        $stmt=$conn->prepare('INSERT INTO fee_schedules (fee_structure_id,due_date,amount) VALUES (?,?,?) ON DUPLICATE KEY UPDATE amount=VALUES(amount), status=1');$stmt->bind_param('isd',$structure,$date,$amount);
        if ($structure<=0||$amount<0||!$stmt->execute())$error=$stmt->error?:'Enter valid schedule details.';else$message='Fee schedule saved.';$stmt->close();
    } elseif ($action==='concession') {
        $student=(int)$_POST['student_id'];$type=(int)$_POST['concession_fee_type'];$name=trim((string)$_POST['concession_name']);$amount=(float)$_POST['concession_amount'];
        $stmt=$conn->prepare('INSERT INTO student_fee_concessions (student_id,fee_type_id,concession_name,amount,valid_from,valid_to) VALUES (?,NULLIF(?,0),?,?,NULLIF(?,\'\'),NULLIF(?,\'\'))');$from=(string)$_POST['valid_from'];$to=(string)$_POST['valid_to'];$stmt->bind_param('iisdss',$student,$type,$name,$amount,$from,$to);
        if($student<=0||$name===''||$amount<0||!$stmt->execute())$error=$stmt->error?:'Enter valid concession details.';else$message='Student concession saved.';$stmt->close();
    } elseif ($action==='payment') {
        $student=(int)$_POST['payment_student'];$type=(int)$_POST['payment_fee_type'];$date=(string)$_POST['payment_date'];$amount=(float)$_POST['payment_amount'];$receipt=trim((string)$_POST['receipt_no']);$remarks=trim((string)$_POST['payment_remarks']);$by=(int)($_SESSION['user_id']??0);
        $stmt=$conn->prepare('INSERT INTO fee_payments (student_id,fee_type_id,payment_date,amount,receipt_no,remarks,created_by) VALUES (?,NULLIF(?,0),?,?,NULLIF(?,\'\'),?,?)');$stmt->bind_param('iisdssi',$student,$type,$date,$amount,$receipt,$remarks,$by);
        if($student<=0||$amount<=0||!$stmt->execute())$error=$stmt->errno===1062?'Receipt number already exists.':($stmt->error?:'Enter valid payment details.');else$message='Fee payment recorded.';$stmt->close();
    }
}
$types=array();$classes=array();$students=array();$structures=array();$schedules=array();$concessions=array();$ledger=array();$selected_student=(int)($_GET['student_id']??0);
$r=$conn->query('SELECT id,fee_name FROM fee_types WHERE status=1 ORDER BY fee_name');while($r&&($x=$r->fetch_assoc()))$types[]=$x;
$r=$conn->query('SELECT id,class_name FROM classes WHERE status=1 ORDER BY class_order');while($r&&($x=$r->fetch_assoc()))$classes[]=$x;
$r=access_is_student() ? $conn->query('SELECT id,student_name,admission_no,class_id FROM students WHERE id=' . access_student_id() . ' AND status=1') : $conn->query('SELECT id,student_name,admission_no,class_id FROM students WHERE status=1 ORDER BY student_name');while($r&&($x=$r->fetch_assoc()))$students[]=$x;
$r=$conn->query('SELECT fs.id,fs.amount,fs.frequency,c.class_name,ft.fee_name FROM fee_structures fs JOIN classes c ON c.id=fs.class_id JOIN fee_types ft ON ft.id=fs.fee_type_id WHERE fs.status=1 ORDER BY c.class_name,ft.fee_name');while($r&&($x=$r->fetch_assoc()))$structures[]=$x;
$r=$conn->query('SELECT f.id,f.due_date,f.amount,c.class_name,ft.fee_name FROM fee_schedules f JOIN fee_structures fs ON fs.id=f.fee_structure_id JOIN classes c ON c.id=fs.class_id JOIN fee_types ft ON ft.id=fs.fee_type_id WHERE f.status=1 ORDER BY f.due_date DESC LIMIT 100');while($r&&($x=$r->fetch_assoc()))$schedules[]=$x;
$r=$conn->query('SELECT c.id,c.concession_name,c.amount,s.student_name,ft.fee_name FROM student_fee_concessions c JOIN students s ON s.id=c.student_id LEFT JOIN fee_types ft ON ft.id=c.fee_type_id WHERE c.status=1 ORDER BY c.created_at DESC LIMIT 100');while($r&&($x=$r->fetch_assoc()))$concessions[]=$x;
if(access_is_student()){$selected_student=access_student_id();} if($selected_student>0){$stmt=$conn->prepare("SELECT ft.fee_name,SUM(f.amount) billed,COALESCE((SELECT SUM(p.amount) FROM fee_payments p WHERE p.student_id=? AND (p.fee_type_id=f.fee_type_id OR p.fee_type_id IS NULL)),0) paid,COALESCE((SELECT SUM(c.amount) FROM student_fee_concessions c WHERE c.student_id=? AND (c.fee_type_id=f.fee_type_id OR c.fee_type_id IS NULL) AND c.status=1),0) concession FROM fee_schedules f JOIN fee_structures fs ON fs.id=f.fee_structure_id JOIN fee_types ft ON ft.id=fs.fee_type_id WHERE f.status=1 AND fs.class_id=(SELECT class_id FROM students WHERE id=?) GROUP BY f.fee_type_id,ft.fee_name");$stmt->bind_param('iii',$selected_student,$selected_student,$selected_student);$stmt->execute();$q=$stmt->get_result();while($x=$q->fetch_assoc())$ledger[]=$x;$stmt->close();}
?>
<?php include '../../includes/header.php'; ?><?php include '../../includes/navbar.php'; ?><?php include '../../includes/sidebar.php'; ?>
<div class="content-wrapper"><section class="content-header"><div class="container-fluid"><h1><i class="fas fa-rupee-sign"></i> Fees</h1></div></section><section class="content"><div class="container-fluid">
<?php if($message): ?><div class="alert alert-success"><?=fee_e($message)?></div><?php endif;?><?php if($error): ?><div class="alert alert-danger"><?=fee_e($error)?></div><?php endif;?>
<div class="row"><div class="col-md-4"><div class="card"><div class="card-header bg-primary text-white">Add Type of Fee</div><div class="card-body"><form method="post"><input type="hidden" name="action" value="type"><input name="fee_name" class="form-control mb-2" placeholder="Tuition Fee" required><input name="description" class="form-control mb-2" placeholder="Description"><button class="btn btn-success">Add Fee Type</button></form></div></div></div><div class="col-md-8"><div class="card"><div id="structure" class="card-header bg-info text-white">View / Add Fee Structure</div><div class="card-body"><form method="post" class="row"><input type="hidden" name="action" value="structure"><div class="col-md-3"><select name="class_id" class="form-control mb-2" required><option value="">Class</option><?php foreach($classes as $x):?><option value="<?=$x['id']?>"><?=fee_e($x['class_name'])?></option><?php endforeach;?></select></div><div class="col-md-3"><select name="fee_type_id" class="form-control mb-2" required><option value="">Fee type</option><?php foreach($types as $x):?><option value="<?=$x['id']?>"><?=fee_e($x['fee_name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input name="amount" type="number" step="0.01" class="form-control mb-2" placeholder="Amount" required></div><div class="col-md-2"><select name="frequency" class="form-control mb-2"><option>Monthly</option><option>Quarterly</option><option>Annual</option><option>One Time</option></select></div><div class="col-md-2"><button class="btn btn-success">Save</button></div></form><table class="table table-sm"><tr><th>Class</th><th>Fee</th><th>Amount</th><th>Frequency</th></tr><?php foreach($structures as $x):?><tr><td><?=fee_e($x['class_name'])?></td><td><?=fee_e($x['fee_name'])?></td><td>â‚¹<?=number_format($x['amount'],2)?></td><td><?=fee_e($x['frequency'])?></td></tr><?php endforeach;?></table></div></div></div></div>
<div class="row"><div class="col-md-6"><div class="card"><div id="schedule" class="card-header bg-warning">View / Add Fee Schedule</div><div class="card-body"><form method="post" class="row"><input type="hidden" name="action" value="schedule"><div class="col-md-5"><select name="fee_structure_id" class="form-control mb-2" required><option value="">Fee structure</option><?php foreach($structures as $x):?><option value="<?=$x['id']?>"><?=fee_e($x['class_name'].' - '.$x['fee_name'].' - â‚¹'.$x['amount'])?></option><?php endforeach;?></select></div><div class="col-md-3"><input type="date" name="due_date" class="form-control mb-2" required></div><div class="col-md-2"><input type="number" step="0.01" name="schedule_amount" class="form-control mb-2" placeholder="Amount" required></div><div class="col-md-2"><button class="btn btn-success">Save</button></div></form><table class="table table-sm"><tr><th>Due</th><th>Class/Fee</th><th>Amount</th></tr><?php foreach($schedules as $x):?><tr><td><?=fee_e($x['due_date'])?></td><td><?=fee_e($x['class_name'].' / '.$x['fee_name'])?></td><td>â‚¹<?=number_format($x['amount'],2)?></td></tr><?php endforeach;?></table></div></div></div>
<div class="col-md-6"><div class="card"><div id="concession" class="card-header bg-success text-white">View / Add Fee Concession</div><div class="card-body"><form method="post" class="row"><input type="hidden" name="action" value="concession"><div class="col-md-6"><select name="student_id" class="form-control mb-2" required><option value="">Student</option><?php foreach($students as $x):?><option value="<?=$x['id']?>"><?=fee_e($x['student_name'].' - '.$x['admission_no'])?></option><?php endforeach;?></select></div><div class="col-md-6"><select name="concession_fee_type" class="form-control mb-2"><option value="">All fee types</option><?php foreach($types as $x):?><option value="<?=$x['id']?>"><?=fee_e($x['fee_name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><input name="concession_name" class="form-control mb-2" placeholder="Concession name" required></div><div class="col-md-6"><input name="concession_amount" type="number" step="0.01" class="form-control mb-2" placeholder="Amount" required></div><div class="col-md-6"><input name="valid_from" type="date" class="form-control mb-2"></div><div class="col-md-6"><input name="valid_to" type="date" class="form-control mb-2"></div><div class="col-12"><button class="btn btn-success">Save Concession</button></div></form><table class="table table-sm"><tr><th>Student</th><th>Concession</th><th>Amount</th></tr><?php foreach($concessions as $x):?><tr><td><?=fee_e($x['student_name'])?></td><td><?=fee_e($x['concession_name'])?></td><td>â‚¹<?=number_format($x['amount'],2)?></td></tr><?php endforeach;?></table></div></div></div></div>
<div class="card"><div class="card-header bg-secondary text-white">Student Fees / Payments</div><div class="card-body"><form method="get" class="form-inline mb-3"><select name="student_id" class="form-control mr-2" required><option value="">Select student to view fees</option><?php foreach($students as $x):?><option value="<?=$x['id']?>" <?=$selected_student===$x['id']?'selected':''?>><?=fee_e($x['student_name'].' - '.$x['admission_no'])?></option><?php endforeach;?></select><button class="btn btn-primary">View Fees</button></form><?php if($selected_student):?><table class="table table-bordered"><tr><th>Fee</th><th>Billed</th><th>Concession</th><th>Paid</th><th>Balance</th></tr><?php foreach($ledger as $x):$balance=max(0,(float)$x['billed']-(float)$x['concession']-(float)$x['paid']);?><tr><td><?=fee_e($x['fee_name'])?></td><td>â‚¹<?=number_format($x['billed'],2)?></td><td>â‚¹<?=number_format($x['concession'],2)?></td><td>â‚¹<?=number_format($x['paid'],2)?></td><td><strong>â‚¹<?=number_format($balance,2)?></strong></td></tr><?php endforeach;?></table><form method="post" class="row"><input type="hidden" name="action" value="payment"><input type="hidden" name="payment_student" value="<?=$selected_student?>"><div class="col-md-2"><select name="payment_fee_type" class="form-control"><option value="">All fees</option><?php foreach($types as $x):?><option value="<?=$x['id']?>"><?=fee_e($x['fee_name'])?></option><?php endforeach;?></select></div><div class="col-md-2"><input type="date" name="payment_date" value="<?=date('Y-m-d')?>" class="form-control" required></div><div class="col-md-2"><input type="number" step="0.01" name="payment_amount" class="form-control" placeholder="Amount" required></div><div class="col-md-2"><input name="receipt_no" class="form-control" placeholder="Receipt no"></div><div class="col-md-3"><input name="payment_remarks" class="form-control" placeholder="Remarks"></div><div class="col-md-1"><button class="btn btn-success">Pay</button></div></form><?php else:?><p class="text-muted">Select a student to see billed fees, concessions, payments, and balance.</p><?php endif;?></div></div>
</div></section></div><?php include '../../includes/footer.php'; ?>
